@startuml

class Home {
  + Name : string
}

class Department {
  + Name : string
}

class Room {
  + RoomNumber : string
}

class Bed {
  + BedNumber : string
}

class Category {
  + Name : string
  + Price : double
}

class StayType {
  + Name : string
}

class RestHome {
  + Name : string
}

class RestNursingHome {
  + Name : string
}

class ServiceFlat {
  + Name : string
}

class Inhabitant {
  + Name : string
  + IdentificationData : string
  + RegistrationDate : date
}

class Registration {
  + Questions : string
}

class Assessment {
  + NeedsForHelp : string
  + ResultingStayType : string
}

class WaitingList {
  + Position : int
}

class Proposal {
  + Date : date
  + Status : string
}

class Invoice {
  + InvoiceNumber : int
  + OutstandingAmount : double
  + Status : string
}

class CreditNote {
  + Amount : double
}

class Stay {
  + StartDate : date
  + IsSuspended : boolean
  + DiscountApplied : boolean
}

Home "1" *-- "1..*" Department
Department "1" *-- "1..*" Room
Room "1" *-- "1..*" Bed
Bed "1" -- "1" Category
StayType "1" -- "1..*" Category

StayType <|-- RestHome
StayType <|-- RestNursingHome
StayType <|-- ServiceFlat

Inhabitant "1" -- "1..*" Stay
Stay "1" -- "1" StayType
Stay "1" -- "1" Bed

Inhabitant "1" -- "1" Registration
Registration "1" -- "1" Assessment
Assessment "1" -- "1" StayType

StayType "1" -- "1" WaitingList
WaitingList "1" -- "1..*" Inhabitant

Proposal "1" -- "1" Inhabitant
Proposal "1" -- "1" Bed
Proposal "1" -- "1" StayType

Stay "1" -- "0..*" Invoice
Invoice "1" -- "0..*" CreditNote

@enduml

